import React, { useState } from 'react';
import logo from '../images/Logo.png'; 

const EventCreationForm = () => {
  const [emailFields, setEmailFields] = useState([]);  // Состояние для хранения почтовых полей

  // Функция для добавления нового поля ввода почты
  const addEmailField = () => {
    setEmailFields([...emailFields, ""]); // Добавляем новое пустое поле в массив
  };

  // Функция для обработки изменения почты
  const handleEmailChange = (index, event) => {
    const newEmailFields = [...emailFields];
    newEmailFields[index] = event.target.value; // Обновляем значение почты по индексу
    setEmailFields(newEmailFields);
  };

  return (
    <div className="creating-page">
      <header className="main-header"></header>
      <div className="page-main">
        <div className="left-sidebar">
          <img src={logo} alt="logo" />
          <h3>Система учета<br /> посещаемости</h3>
        </div>
        <div className="content">
          <h1>Создание мероприятия</h1>
          <div className="createForm">
            <h3>Название мероприятия</h3>
            <input type="text" placeholder="Напишите название мероприятия" />

            <h3>Выберите тип мероприятия</h3>
            <select>
              <option value="" disabled selected>
                Выберите тип мероприятия
              </option>
              <option value="seminar">Семинар</option>
              <option value="competition">Соревнования</option>
              <option value="conference">Конференция</option>
            </select>

            <h3>Дата проведения</h3>
            <div>
              <input type="datetime-local" className="datetime-input" />
            </div>

            <h3>Добавьте проверяющего(-их)</h3>

            {/* Первоначальное поле для почты */}
            <div>
              <input
                type="text"
                placeholder="Введите почту проверяющего"
                value={emailFields[0]} // Первое поле для почты
                onChange={(e) => handleEmailChange(0, e)} // Обрабатываем изменение первого поля
              />
            </div>

            {/* Поля для остальных почт */}
            {emailFields.slice(1).map((email, index) => (
              <div key={index + 1}>
                <input
                  type="text"
                  placeholder="Введите почту проверяющего"
                  value={email}
                  onChange={(e) => handleEmailChange(index + 1, e)} 
                />
              </div>
            ))}

            <button type="button"
              onClick={addEmailField}
              style={{ marginTop: '10px' }}
            >
              Добавить проверяющего
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default EventCreationForm;
